-- ----------------------------------------------------------------------------
-- Drop pass: every rulebook-owned view, reverse iteration order, CASCADE.
-- The rulebook is HEAD — the surviving view set must mirror it exactly.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_hockett_assessments CASCADE;
DROP VIEW IF EXISTS vw_hockett_features CASCADE;
DROP VIEW IF EXISTS vw_is_everything_a_language CASCADE;
DROP VIEW IF EXISTS vw_language_candidates CASCADE;

-- ----------------------------------------------------------------------------
-- vw_language_candidates: Table: LanguageCandidates
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_language_candidates CASCADE;
CREATE VIEW vw_language_candidates WITH (security_invoker = ON) AS
SELECT
  t.language_candidate_id,
  t.name,                                                                       -- Name of the language candidate being classified.
  t.is_language,                                                                -- The test answer that is intended to match the Family Feud answer to be "correct".
  calc_language_candidates_has_grammar(t.language_candidate_id) AS has_grammar, -- Does this candidate have a Grammar?  Generally follows candidates that have syntax also have grammar.
  t.has_syntax,                                                                 -- Does this language candidate have syntax and/or grammar?
  t.can_be_held,                                                                -- Is this candidate physical/material.  I.e. could it at least theoretically "be held"?
  calc_language_candidates_question(t.language_candidate_id) AS question,       -- Question that 100 random people could be asked, family feud style.
  calc_language_candidates_predicted_answer(t.language_candidate_id) AS predicted_answer,-- The predicted answer as the top most popular answer among those in the family feud polling pool.
  calc_language_candidates_prediction_predicates(t.language_candidate_id) AS prediction_predicates,
  calc_language_candidates_prediction_fail(t.language_candidate_id) AS prediction_fail,-- If the family feud answer does not match the chosen language candidates status then this explains what did not match. t also flags (in english) mismatch where a candidate is marked as BOTH open AND closed world which does not make sense.
  t.category,                                                                   -- The general high level category of the candidate.
  t.has_identity,                                                               -- Could this thing be assigned a guid, unique in the universe that would identify it globally?  Like a drivers license or social security number for a person.
  t.is_parsed,                                                                  -- Is the knowledge/information encoded in a form that requires parsing before meaning can be extracted?
  t.resolves_to_an_ast,                                                         -- Is the knowledge/information encoded in a form that requires parsing before meaning can be extracted?
  t.has_linear_decoding_pressure,
  t.is_stable_ontology_reference,
  t.is_live_ontology_editor,
  t.is_open_world,
  t.is_closed_world,
  calc_language_candidates_is_description_of(t.language_candidate_id) AS is_description_of,
  t.distance_from_concept,
  calc_language_candidates_is_open_closed_world_conflicted(t.language_candidate_id) AS is_open_closed_world_conflicted,
  t.dimensionality_while_editing,
  calc_language_candidates_relationship_to_concept(t.language_candidate_id) AS relationship_to_concept,
  t.model_object_facility_layer,
  t.sort_order,
  calc_language_candidates_hockett_assessed_count(t.language_candidate_id) AS hockett_assessed_count,-- How many of Hockett's design features this candidate has a published assessment for. Zero means nobody has assessed it, which is not the same as failing.
  calc_language_candidates_hockett_yes_count(t.language_candidate_id) AS hockett_yes_count,-- How many assessed design features this candidate satisfies outright.
  calc_language_candidates_is_hockett_assessed(t.language_candidate_id) AS is_hockett_assessed,-- TRUE once this candidate has at least one published design-feature assessment.
  calc_language_candidates_hockett_score(t.language_candidate_id) AS hockett_score,-- The design-feature tally as text, reading "not assessed" rather than "0" when there is no published assessment. A hand-written Postgres function used to sum eleven bio_has_* columns that were never in the rulebook, so every candidate silently scored zero; this field replaces it.
  calc_language_candidates_hockett_vs_gate(t.language_candidate_id) AS hockett_vs_gate-- Names the disagreement, in English, when the eight-clause gate and Hockett's design features reach opposite conclusions. Empty when they agree or when the candidate is unassessed.
FROM language_candidates t;

-- ----------------------------------------------------------------------------
-- vw_is_everything_a_language: Table: IsEverythingALanguage
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_is_everything_a_language CASCADE;
CREATE VIEW vw_is_everything_a_language WITH (security_invoker = ON) AS
SELECT
  t.is_everything_a_language_id,
  t.name,
  t.argument_name,
  t.argument_category,
  t.step_type,
  t.statement,
  t.formalization,
  t.related_candidate_name,
  t.related_candidate_id,
  t.evidence_from_rulebook,
  t.notes
FROM is_everything_a_language t;

-- ----------------------------------------------------------------------------
-- vw_hockett_features: Table: HockettFeatures
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_hockett_features CASCADE;
CREATE VIEW vw_hockett_features WITH (security_invoker = ON) AS
SELECT
  t.hockett_feature_id,
  t.name,                                                                       -- The design feature's name, as Hockett gives it.
  t.feature_number,                                                             -- Hockett's own numbering, 1 through 13, then 14 through 16 for the 1968 additions.
  t.definition,                                                                 -- What the feature asserts, in plain English.
  t.is_original_thirteen,                                                       -- TRUE for the thirteen features of the 1960 paper; FALSE for the three added in 1968.
  t.source,                                                                     -- Citation for the feature list.
  calc_hockett_features_assessment_count(t.hockett_feature_id) AS assessment_count,-- How many candidates have been assessed against this feature.
  calc_hockett_features_yes_count(t.hockett_feature_id) AS yes_count            -- How many assessed candidates satisfy this feature outright.
FROM hockett_features t;

-- ----------------------------------------------------------------------------
-- vw_hockett_assessments: Table: HockettAssessments
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_hockett_assessments CASCADE;
CREATE VIEW vw_hockett_assessments WITH (security_invoker = ON) AS
SELECT
  t.hockett_assessment_id,
  calc_hockett_assessments_name(t.hockett_assessment_id) AS name,               -- Logical key: the candidate and the feature being assessed.
  t.language_candidate,                                                         -- FK to the candidate being assessed.
  t.hockett_feature,                                                            -- FK to the design feature being applied.
  t.verdict,                                                                    -- Yes, No, Partial or Unknown. Partial and Unknown exist because the published assessments hedge, and flattening a hedge into a boolean would bury a judgement call in the data.
  t.verbatim_assessment,                                                        -- The source's exact wording for this cell, so every resolution to Verdict stays auditable.
  t.source_citation,                                                            -- Where this cell came from, including which column.
  t.mapping_note,                                                               -- Empty when this candidate corresponds exactly to the source's column. Otherwise, how the two differ and how far the row should be trusted.
  calc_hockett_assessments_is_yes_flag(t.hockett_assessment_id) AS is_yes_flag  -- 1 when the verdict is an outright Yes, else 0. Summed by the rollups on LanguageCandidates and HockettFeatures.
FROM hockett_assessments t;

